import fs from "node:fs";
import path from "node:path";

const raiz = process.cwd();
const serverPath = path.join(raiz,"server","comprasPecas.ts");
const compPath = path.join(raiz,"client","src","components","ComprasPecasCotacao.tsx");
const pagePath = path.join(raiz,"client","src","pages","ComprasPecas.tsx");
const routersPath = path.join(raiz,"server","routers.ts");

function falhar(msg){throw new Error(`PATCH COMPRAS PEÇAS V2: ${msg}`);}
function ler(p){if(!fs.existsSync(p))falhar(`arquivo não encontrado: ${p}`);const b=fs.readFileSync(p,"utf8");const bom=b.startsWith("\uFEFF")?"\uFEFF":"";const c=bom?b.slice(1):b;const eol=c.includes("\r\n")?"\r\n":"\n";return{bom,eol,texto:c.replace(/\r\n/g,"\n")};}
function montar(i,t){return i.bom+t.replace(/\n/g,i.eol);}
function sub(t,a,n,r){const c=t.split(a).length-1;if(c!==1)falhar(`${r}: esperava 1 ocorrência, encontrei ${c}. Nada foi gravado.`);return t.replace(a,n);}

if(fs.existsSync(serverPath)||fs.existsSync(compPath))falhar("a V2 parece já estar aplicada.");
const pageInfo=ler(pagePath);const routersInfo=ler(routersPath);let page=pageInfo.texto;let routers=routersInfo.texto;
if(!page.includes("Planejamento de peças"))falhar("a V1 de Peças precisa estar aplicada.");
if(!routers.includes('import { comprasPneusRouter } from "./comprasPneus";'))falhar("não encontrei comprasPneusRouter.");
routers=sub(routers,'import { comprasPneusRouter } from "./comprasPneus";','import { comprasPneusRouter } from "./comprasPneus";\nimport { comprasPecasRouter } from "./comprasPecas";',"import comprasPecasRouter");
routers=sub(routers,'    pneus: comprasPneusRouter,','    pneus: comprasPneusRouter,\n    pecas: comprasPecasRouter,',"subrouter compras.pecas");
page=sub(page,'import * as XLSX from "xlsx";','import * as XLSX from "xlsx";\nimport ComprasPecasCotacao from "@/components/ComprasPecasCotacao";',"import componente cotação");
const footer='        <footer className="mt-8 border-t border-white/[0.05] py-5 text-center text-[11px] text-gray-700">';
page=sub(page,footer,'        {arquivoNome && (\n          <ComprasPecasCotacao arquivoNome={arquivoNome} itens={itens} />\n        )}\n\n'+footer,"componente cotação e pedidos");
const agora=new Date();const s=String(agora.getFullYear())+String(agora.getMonth()+1).padStart(2,"0")+String(agora.getDate()).padStart(2,"0")+String(agora.getHours()).padStart(2,"0")+String(agora.getMinutes()).padStart(2,"0")+String(agora.getSeconds()).padStart(2,"0");
const backup=path.join(raiz,`.backup-compras-pecas-v2-${s}`);
for(const [rel,orig] of [["client/src/pages/ComprasPecas.tsx",pagePath],["server/routers.ts",routersPath]]){const d=path.join(backup,rel);fs.mkdirSync(path.dirname(d),{recursive:true});fs.copyFileSync(orig,d);}
const tmpPage=pagePath+".v2.tmp",tmpRouters=routersPath+".v2.tmp",tmpServer=serverPath+".v2.tmp",tmpComp=compPath+".v2.tmp";
try{fs.mkdirSync(path.dirname(compPath),{recursive:true});fs.writeFileSync(tmpPage,montar(pageInfo,page),"utf8");fs.writeFileSync(tmpRouters,montar(routersInfo,routers),"utf8");fs.writeFileSync(tmpServer,Buffer.from("","base64"));fs.writeFileSync(tmpComp,Buffer.from("","base64"));fs.renameSync(tmpPage,pagePath);fs.renameSync(tmpRouters,routersPath);fs.renameSync(tmpServer,serverPath);fs.renameSync(tmpComp,compPath);}catch(e){for(const p of [tmpPage,tmpRouters,tmpServer,tmpComp])if(fs.existsSync(p))fs.unlinkSync(p);try{fs.copyFileSync(path.join(backup,"client/src/pages/ComprasPecas.tsx"),pagePath);fs.copyFileSync(path.join(backup,"server/routers.ts"),routersPath);}catch{}if(fs.existsSync(serverPath))fs.unlinkSync(serverPath);if(fs.existsSync(compPath))fs.unlinkSync(compPath);throw e;}
console.log("");console.log("✅ Compras > Peças V2 aplicado.");console.log(`✅ Backup: ${path.relative(raiz,backup)}`);console.log("✅ Fornecedores, cotação por planilha, pedidos e histórico adicionados.");console.log("✅ Clique no fornecedor abre Baixar cotação / Anexar preenchida.");console.log("✅ Quantidade continua interna e não vai para o fornecedor.");console.log("✅ Pedidos ficam salvos e o Excel do pedido sai bloqueado com total.");console.log("O patch NÃO fez commit.");
